mapper.select:
select
    a.id, a.username, a.email, a.status, a.deleted, a.create_time, a.update_time,
    b.avatar, b.user_role, b.nickname
from user_account a
left join user_info b on a.id = b.user_id

    and a.status = #{queryParam.status}
    and a.deleted = #{queryParam.deleted}
    and a.create_time >= #{queryParam.startTime}
    and a.create_time <= #{queryParam.endTime}

        and a.username like concat('%', #{queryParam.username}, '%')


order by a.create_time desc
